const $=id=>document.getElementById(id);let data,deck=[],index=0,category='All words',generation=0,currentAudio;const colors=['#fff1cc','#e4f3fc','#fce7de','#e9edf9','#e5f3df'];
function stop(){generation++;if(currentAudio){currentAudio.pause();currentAudio=null}if('speechSynthesis'in window)speechSynthesis.cancel();$('card').classList.remove('speaking')}
function draw(){stop();const item=deck[index];$('word').textContent=item.word;$('picture').textContent=item.picture||'';$('picture').hidden=!!item.image;$('image').hidden=!item.image;if(item.image){$('image').src=item.image;$('image').alt=item.word}$('card').style.background=colors[index%colors.length];$('card').setAttribute('aria-label',`Hear ${item.word}`);$('category').textContent=item.category;$('count').textContent=`${index+1} / ${deck.length}`;$('progress').style.width=`${(index+1)/deck.length*100}%`;$('segments').replaceChildren();$('status').textContent='';$('sound').disabled=!item.sounds?.length}
function choose(name){category=name;deck=data.items.filter(x=>name==='All words'||x.category===name);index=0;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.textContent===name));draw()}
function speak(text,url,rate=0.8){return new Promise(resolve=>{if(url){const a=new Audio(url);currentAudio=a;a.onended=resolve;a.onerror=()=>{ $('status').textContent='That recording could not play.';resolve()};a.play().catch(()=>{$('status').textContent='Tap again to play the recording.';resolve()});return}if(!('speechSynthesis'in window)){$('status').textContent='Speech is unavailable in this browser. Try Chrome or Safari.';resolve();return}const u=new SpeechSynthesisUtterance(text);u.lang=data.language||'en-CA';u.rate=rate;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang===u.lang)||voices.find(v=>v.lang.startsWith('en'))||null;u.onend=resolve;u.onerror=resolve;speechSynthesis.speak(u)})}
async function hear(){stop();const token=generation,item=deck[index];$('card').classList.add('speaking');await speak(item.speech||item.word,item.audio);if(token===generation)$('card').classList.remove('speaking')}
async function sound(){stop();const token=generation,item=deck[index];$('segments').replaceChildren(...item.sounds.map(s=>{const e=document.createElement('span');e.textContent=s.label;return e}));for(let i=0;i<item.sounds.length;i++){if(token!==generation)return;const s=item.sounds[i],e=$('segments').children[i];e.classList.add('speaking');await speak(s.say,s.audio,0.65);if(token!==generation)return;e.classList.remove('speaking');await new Promise(r=>setTimeout(r,220))}if(token===generation)await speak(item.word,item.audio,0.7)}
function move(n){index=(index+n+deck.length)%deck.length;draw()}
$('card').onclick=e=>{if(performance.now()<suppressClickUntil){e.preventDefault();return}hear()};$('hear').onclick=hear;$('sound').onclick=sound;$('prev').onclick=()=>move(-1);$('next').onclick=()=>move(1);$('shuffle').onclick=()=>{for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}index=0;draw()};document.addEventListener('keydown',e=>{if(e.key==='ArrowRight')move(1);if(e.key==='ArrowLeft')move(-1)});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
fetch('./words.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(json=>{data=json;if(!data.items?.length)throw Error();for(const name of ['All words',...new Set(data.items.map(x=>x.category))]){const b=document.createElement('button');b.textContent=name;b.onclick=()=>choose(name);$('categories').append(b)}choose('All words')}).catch(()=>{$('status').textContent='The cards could not load. Please refresh to try again.';document.querySelectorAll('button').forEach(b=>b.disabled=true)});

// A viewport-filling fallback also works on phones without the Fullscreen API.
let fullMode=false,suppressClickUntil=0,gesture=null;
const play=$('play'),card=$('card');
function setFullMode(enabled){
 fullMode=enabled;document.body.classList.toggle('full-mode',enabled);
 $('fullscreen').hidden=enabled;$('fullscreen').setAttribute('aria-pressed',String(enabled));$('exit-fullscreen').hidden=!enabled;
 document.querySelectorAll('main > header, main > .intro, main > nav, main > footer').forEach(e=>e.inert=enabled);
 $('progress-label').textContent=enabled?'Swipe left or right':'One little word at a time';
 (enabled?$('exit-fullscreen'):$('fullscreen')).focus({preventScroll:true});
}
$('fullscreen').onclick=()=>{setFullMode(true);if(play.requestFullscreen){try{const request=play.requestFullscreen();if(request?.catch)request.catch(()=>{});}catch{}}};
function exitFullMode(){setFullMode(false);if(document.fullscreenElement&&document.exitFullscreen)document.exitFullscreen().catch(()=>{});}
$('exit-fullscreen').onclick=exitFullMode;
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&fullMode)setFullMode(false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&fullMode)exitFullMode()});
card.addEventListener('pointerdown',e=>{if(!e.isPrimary||e.button!==0)return;gesture={id:e.pointerId,x:e.clientX,y:e.clientY,dx:0};card.setPointerCapture(e.pointerId);});
card.addEventListener('pointermove',e=>{if(!gesture||gesture.id!==e.pointerId)return;gesture.dx=e.clientX-gesture.x;const dy=e.clientY-gesture.y;if(Math.abs(gesture.dx)>12&&Math.abs(gesture.dx)>Math.abs(dy)){card.classList.add('dragging');card.style.transform=`translateX(${Math.max(-120,Math.min(120,gesture.dx))*0.45}px) rotate(${gesture.dx*0.015}deg)`;}});
function finishGesture(e,cancelled=false){if(!gesture||gesture.id!==e.pointerId)return;const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;gesture=null;card.classList.remove('dragging');card.style.transform='';if(Math.abs(dx)>12||Math.abs(dy)>12)suppressClickUntil=performance.now()+500;if(!cancelled&&Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)*1.25){move(dx<0?1:-1);if(!matchMedia('(prefers-reduced-motion: reduce)').matches)card.animate([{opacity:0.3,transform:`translateX(${dx<0?30:-30}px)`},{opacity:1,transform:'translateX(0)'}],{duration:180,easing:'ease-out'});}}
card.addEventListener('pointerup',e=>finishGesture(e));card.addEventListener('pointercancel',e=>finishGesture(e,true));
